import type { CSSProperties, ReactNode } from 'react'
import './index.less'

interface SolutionSectionProps {
  image: string
  imageAlt?: string
  imageWidth: number
  imageHeight: number
  reverse?: boolean
  children: ReactNode
  className?: string
  style?: CSSProperties
  padding?: string
  gap?: number
  imageBorderRadius?: number
}

const SolutionSection = ({
  image,
  imageAlt = '',
  imageWidth,
  imageHeight,
  reverse = false,
  children,
  className = '',
  style,
  padding,
  gap = 100,
  imageBorderRadius = 16,
}: SolutionSectionProps) => {
  const sectionStyle = {
    ...style,
    ...(padding
      ? {
          '--section-padding-top': padding.split(/\s+/)[0],
          '--section-padding-bottom': padding.split(/\s+/)[2],
        }
      : {}),
    ...(gap ? { '--section-gap': `${gap}px` } : {}),
  } as CSSProperties

  const imageStyle = {
    '--section-image-width': `${imageWidth}px`,
    '--section-image-ratio': `${imageWidth} / ${imageHeight}`,
    '--section-image-radius': `${imageBorderRadius}px`,
  } as CSSProperties

  return (
    <section
      className={`solution-section ${reverse ? 'solution-section--reverse' : ''} ${className}`}
      style={sectionStyle}
    >
      <div className="solution-section__image" style={imageStyle}>
        <img src={image} alt={imageAlt} />
      </div>
      <div className="solution-section__content">{children}</div>
    </section>
  )
}

export default SolutionSection
